import json
import os
import sys

# Mapping from fact names to the JSON field that establishes them.
FACT_FIELD_MAP = {
    "initiation date": "recall_initiation_date",
    "classification date": "center_classification_date",
    "termination date": "termination_date",
}

def convert_date(val):
    """Convert a date string from YYYYMMDD to YYYY-MM-DD.
    Return None if the value is empty or not a usable date."""
    if not val:
        return None
    val = val.strip()
    if len(val) == 8 and val.isdigit():
        return f"{val[:4]}-{val[4:6]}-{val[6:8]}"
    if len(val) == 10 and val[4] == '-' and val[7] == '-':
        return val
    return val

def load_records(packet_dir):
    """Load all records from the FDA enforcement reports JSON file.
    Returns a list of (record_dict, document_name) tuples."""
    target = None
    # Prefer the file named fda_enforcement_reports.json
    for fname in os.listdir(packet_dir):
        if fname.endswith('.json'):
            stem = os.path.splitext(fname)[0]
            if stem == 'fda_enforcement_reports':
                target = os.path.join(packet_dir, fname)
                break
    # Fallback to any JSON file if the expected one is missing
    if target is None:
        for fname in os.listdir(packet_dir):
            if fname.endswith('.json'):
                target = os.path.join(packet_dir, fname)
                break
    if target is None:
        return []

    with open(target) as f:
        data = json.load(f)

    doc = os.path.splitext(os.path.basename(target))[0]

    if isinstance(data, dict):
        if 'results' in data:
            recs = data['results']
        else:
            recs = [data]
    elif isinstance(data, list):
        recs = data
    else:
        recs = []

    records = []
    for r in recs:
        if isinstance(r, dict):
            records.append((r, doc))
    return records

def main():
    if len(sys.argv) < 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>", file=sys.stderr)
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path) as f:
        manifest = json.load(f)

    records = load_records(packet_dir)
    output = {}

    for pair in manifest["pairs"]:
        rule_id, entity = pair.split("::", 1)
        facts = manifest["facts"].get(rule_id, [])
        pair_result = {}

        for fact in facts:
            field = FACT_FIELD_MAP.get(fact)
            if field is None:
                pair_result[fact] = "ABSENT"
                continue

            # Find all records for this entity (recall number)
            matching = [(r, doc) for r, doc in records if r.get("recall_number") == entity]
            if not matching:
                pair_result[fact] = "ABSENT"
                continue

            # Collect non-empty values for the field
            vals = []
            for r, doc in matching:
                raw = r.get(field, "")
                if raw == "" or raw is None:
                    continue
                val = convert_date(raw)
                if val is None:
                    continue
                vals.append((val, doc))

            if not vals:
                pair_result[fact] = "ABSENT"
            else:
                distinct = set(v[0] for v in vals)
                if len(distinct) == 1:
                    pair_result[fact] = [vals[0][0], vals[0][1]]
                else:
                    pair_result[fact] = "CONFLICT"

        output[pair] = pair_result

    print(json.dumps(output, indent=2))

if __name__ == "__main__":
    main()

