import sys
import json
import os

# Mapping from (rule_id, fact_name) to (document_name, field_name)
# Based on the decision rules provided.
RULE_FACT_MAP = {
    "fda.classified_30d": {
        "initiation date": ("fda_enforcement_reports", "recall_initiation_date"),
        "classification date": ("fda_enforcement_reports", "center_classification_date"),
    },
    "fda.terminated_180d": {
        "initiation date": ("fda_enforcement_reports", "recall_initiation_date"),
        "termination date": ("fda_enforcement_reports", "termination_date"),
    },
}

# Fields that contain dates in YYYYMMDD format and need conversion to YYYY-MM-DD
DATE_FIELDS = {"recall_initiation_date", "center_classification_date", "termination_date"}


def format_date(value):
    """Convert a YYYYMMDD string to YYYY-MM-DD. Leave other strings unchanged."""
    if len(value) == 8 and value.isdigit():
        return f"{value[:4]}-{value[4:6]}-{value[6:]}"
    return value


def load_document(packet_dir, doc_name):
    """Load a JSON document and return a list of records."""
    file_path = os.path.join(packet_dir, doc_name + ".json")
    if not os.path.exists(file_path):
        return []
    with open(file_path, "r", encoding="utf-8") as f:
        data = json.load(f)
    if isinstance(data, dict) and "results" in data:
        return data["results"]
    if isinstance(data, list):
        return data
    return [data]


def index_records(records, id_field):
    """Index records by the value of id_field (e.g., recall_number)."""
    index = {}
    for rec in records:
        if isinstance(rec, dict):
            entity = rec.get(id_field)
            if entity is not None:
                index.setdefault(entity, []).append(rec)
    return index


def main():
    if len(sys.argv) != 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>", file=sys.stderr)
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, "r", encoding="utf-8") as f:
        manifest = json.load(f)

    pairs = manifest.get("pairs", [])
    facts = manifest.get("facts", {})

    # Cache loaded documents and their indices
    doc_cache = {}
    doc_index_cache = {}

    def get_doc_index(doc_name):
        if doc_name not in doc_index_cache:
            records = load_document(packet_dir, doc_name)
            doc_index_cache[doc_name] = index_records(records, "recall_number")
        return doc_index_cache[doc_name]

    output = {}

    for pair in pairs:
        rule_id, entity = pair.split("::", 1)
        fact_names = facts.get(rule_id, [])
        pair_result = {}

        for fact_name in fact_names:
            mapping = RULE_FACT_MAP.get(rule_id, {}).get(fact_name)
            if not mapping:
                pair_result[fact_name] = "ABSENT"
                continue

            doc_name, field_name = mapping
            index = get_doc_index(doc_name)
            records = index.get(entity, [])

            # Collect non-empty values for the field
            values = []
            for rec in records:
                val = rec.get(field_name, "")
                if val is None or val == "":
                    continue
                values.append(val)

            if not values:
                pair_result[fact_name] = "ABSENT"
            else:
                unique_vals = set(values)
                if len(unique_vals) > 1:
                    pair_result[fact_name] = "CONFLICT"
                else:
                    val = values[0]
                    if field_name in DATE_FIELDS:
                        val = format_date(val)
                    pair_result[fact_name] = [val, doc_name]

        output[pair] = pair_result

    print(json.dumps(output, indent=2))


if __name__ == "__main__":
    main()

