import sys
import os
import json
import re

# Hardcoded rule definitions based on the decision rules.
# Each rule maps to a document, an entity field, and a set of facts.
# Each fact maps to (field_name, value_type).
RULES = {
    "fda.classified_30d": {
        "document": "fda_enforcement_reports",
        "entity_field": "recall_number",
        "facts": {
            "initiation date": ("recall_initiation_date", "date"),
            "classification date": ("center_classification_date", "date"),
        },
    },
    "fda.terminated_180d": {
        "document": "fda_enforcement_reports",
        "entity_field": "recall_number",
        "facts": {
            "initiation date": ("recall_initiation_date", "date"),
            "termination date": ("termination_date", "date"),
        },
    },
}


def load_document(packet_dir, doc_name):
    """Load a JSON document from the packet directory.
    Tries <doc_name>.json first, then any file starting with <doc_name>."""
    path = os.path.join(packet_dir, doc_name + ".json")
    if not os.path.exists(path):
        for f in os.listdir(packet_dir):
            if f.startswith(doc_name + "."):
                path = os.path.join(packet_dir, f)
                break
    with open(path, "r", encoding="utf-8") as fh:
        data = json.load(fh)
    if isinstance(data, dict) and "results" in data:
        return data["results"]
    if isinstance(data, list):
        return data
    return [data]


def format_value(value, vtype):
    """Format a raw value according to its type."""
    s = str(value).strip()
    if vtype == "date":
        if re.match(r"^\d{8}$", s):
            return f"{s[:4]}-{s[4:6]}-{s[6:]}"
        if re.match(r"^\d{4}-\d{2}-\d{2}$", s):
            return s
    return s


def main():
    if len(sys.argv) != 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>", file=sys.stderr)
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, "r", encoding="utf-8") as fh:
        manifest = json.load(fh)

    pairs = manifest.get("pairs", [])
    facts_by_rule = manifest.get("facts", {})

    output = {}
    doc_cache = {}

    for pair in pairs:
        if "::" not in pair:
            continue
        rule_id, entity = pair.split("::", 1)
        fact_names = facts_by_rule.get(rule_id, [])
        result = {}

        if rule_id in RULES:
            rule_def = RULES[rule_id]
            doc_name = rule_def["document"]
            entity_field = rule_def["entity_field"]
            facts_map = rule_def["facts"]

            if doc_name not in doc_cache:
                doc_cache[doc_name] = load_document(packet_dir, doc_name)
            records = doc_cache[doc_name]

            # Find all records matching the entity
            matching = [
                r for r in records
                if str(r.get(entity_field, "")).strip() == entity.strip()
            ]

            for fact_name in fact_names:
                if fact_name not in facts_map:
                    result[fact_name] = "ABSENT"
                    continue

                field, vtype = facts_map[fact_name]
                values = []
                for r in matching:
                    if field in r:
                        val = r[field]
                        if val is not None and str(val).strip() != "":
                            values.append(str(val).strip())

                if not values:
                    result[fact_name] = "ABSENT"
                else:
                    unique = set(values)
                    if len(unique) == 1:
                        formatted = format_value(values[0], vtype)
                        result[fact_name] = [formatted, doc_name]
                    else:
                        result[fact_name] = "CONFLICT"
        else:
            # Unknown rule: all facts are ABSENT
            for fact_name in fact_names:
                result[fact_name] = "ABSENT"

        output[pair] = result

    print(json.dumps(output, indent=2))


if __name__ == "__main__":
    main()

