import json
import os
import sys
from datetime import datetime

def parse_date(date_str):
    """Parse a date string and return YYYY-MM-DD format."""
    if not date_str or date_str.strip() == "":
        return None
    date_str = date_str.strip()
    # Try YYYYMMDD format
    try:
        dt = datetime.strptime(date_str, "%Y%m%d")
        return dt.strftime("%Y-%m-%d")
    except ValueError:
        pass
    # Try YYYY-MM-DD format
    try:
        dt = datetime.strptime(date_str, "%Y-%m-%d")
        return dt.strftime("%Y-%m-%d")
    except ValueError:
        pass
    # Return as-is if we can't parse
    return date_str

def main():
    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path) as f:
        manifest = json.load(f)

    # Load the FDA enforcement reports
    fda_file = os.path.join(packet_dir, "fda_enforcement_reports.json")
    with open(fda_file) as f:
        fda_data = json.load(f)

    # Build a map from recall_number to list of records
    records_by_recall = {}
    for record in fda_data.get("results", []):
        recall_num = record.get("recall_number", "")
        if recall_num not in records_by_recall:
            records_by_recall[recall_num] = []
        records_by_recall[recall_num].append(record)

    # Map fact names to field names
    fact_to_field = {
        "initiation date": "recall_initiation_date",
        "classification date": "center_classification_date",
        "termination date": "termination_date",
    }

    # Document name (file name without extension)
    doc_name = "fda_enforcement_reports"

    output = {}

    for pair in manifest["pairs"]:
        rule_id, entity = pair.split("::", 1)
        facts = manifest["facts"].get(rule_id, [])

        result = {}
        for fact_name in facts:
            field_name = fact_to_field.get(fact_name)
            if field_name is None:
                result[fact_name] = "ABSENT"
                continue

            # Find records for this entity
            records = records_by_recall.get(entity, [])

            # Collect values from all matching records
            values = []
            for record in records:
                raw_value = record.get(field_name, "")
                if raw_value is None or (isinstance(raw_value, str) and raw_value.strip() == ""):
                    continue
                # Parse date
                parsed = parse_date(str(raw_value))
                if parsed is not None:
                    values.append(parsed)

            if len(values) == 0:
                result[fact_name] = "ABSENT"
            elif len(values) == 1:
                result[fact_name] = [values[0], doc_name]
            else:
                # Check for conflict
                unique_values = set(values)
                if len(unique_values) == 1:
                    result[fact_name] = [values[0], doc_name]
                else:
                    result[fact_name] = "CONFLICT"

        output[pair] = result

    print(json.dumps(output, indent=2))

if __name__ == "__main__":
    main()

